  "reunion_id": "N3",
  "notas_suficientes": true,
  "preguntas": [],
  "adr": {
    "titulo": "PostgreSQL particionado y caché Redis para series de humedad",
    "estado": "Propuesto",
    "contexto": "El crecimiento a 2000 parcelas con lecturas cada 15s exige mantener latencia p95 <= 500ms.",
    "alternativas": [
      "TimescaleDB",
      "PostgreSQL particionado por mes con índices B-Tree y Redis"
    ],
    "decision": "Usar PostgreSQL particionado por mes con índices B-Tree y caché Redis para lecturas recientes.",
    "consecuencias_positivas": [
      "Aprovecha la experiencia actual del equipo evitando nueva tecnología en el MVP"
    ],
    "consecuencias_negativas": [
      "Aumenta la complejidad de mantener políticas de invalidación de caché"
    ]
  }
}

assert.value:
try {
  const d = JSON.parse(output);
  if (!context.vars.espera_suficiente) {
    return true;
  }
  if (d.notas_suficientes !== true || !d.adr) {
    return false;
  }
  const a = d.adr;
  const tieneContexto = typeof a.contexto === 'string' && a.contexto.trim().length >= 15;
  const tieneDecision = typeof a.decision === 'string' && a.decision.trim().length >= 15;
  const tienePos = Array.isArray(a.consecuencias_positivas) && a.consecuencias_positivas.length >= 1;
  const tieneNeg = Array.isArray(a.consecuencias_negativas) && a.consecuencias_negativas.length >= 1;
  return tieneContexto && tieneDecision && tienePos && tieneNeg;
} catch (e) {
  return false;
}

